            // Expect ':'
            if (CurrentToken?.Type != GeneratedTokenType.OP || CurrentToken?.Value != ":")
            {
                Console.WriteLine($"[DEBUG] ParseLambda: Expected ':' but found {CurrentToken?.Type}:{CurrentToken?.Value}");
